import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { FaHome, FaShoppingCart, FaCashRegister, FaUserShield, FaSignInAlt, FaUserPlus } from 'react-icons/fa';
import './Navbar.css';
import { useSelector } from 'react-redux';

function Navbar() {
  const location = useLocation();
  const cartCount = useSelector(state => state.cart.items.length);
  const { isAuthenticated } = useSelector(state => state.auth);

  // Helper to highlight the active link
  const isActive = (path) => location.pathname === path;

  return (
    <nav className="navbar">
      <Link to="/" className={isActive('/') ? 'active' : ''}>
        <FaHome />
        <span>Home</span>
      </Link>
      <Link to="/cart" className={isActive('/cart') ? 'active' : ''} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
        <FaShoppingCart />
        <span>Cart ({cartCount})</span>
      </Link>
      {!isAuthenticated && (
        <>
          <Link to="/login" className={isActive('/login') ? 'active' : ''}>
            <FaSignInAlt />
            <span>Login</span>
          </Link>
          <Link to="/register" className={isActive('/register') ? 'active' : ''}>
            <FaUserPlus />
            <span>Register</span>
          </Link>
        </>
      )}
      <Link to="/checkout" className={isActive('/checkout') ? 'active' : ''}>
        <FaCashRegister />
        <span>Checkout</span>
      </Link>
      <Link to="/admin" className={isActive('/admin') ? 'active' : ''}>
        <FaUserShield />
        <span>Admin</span>
      </Link>
    </nav>
  );
}

export default Navbar;
